svg.script:
(() => {
  const officialOrigin = "https://nyxlearning.org";
  const applyCloak = event => {
    const frame = document.getElementById("nyxSiteFrame");
    if (!frame || event.origin !== officialOrigin || event.source !== frame.contentWindow || event.data?.type !== "nyx:tab-cloak-sync") return;
    const title = String(event.data.title || "Nyx").trim().slice(0, 120) || "Nyx";
    const favicon = String(event.data.favicon || "").trim();
    const titleElement = document.querySelector("title");
    if (titleElement) titleElement.textContent = title;
    try { document.title = title; } catch {}
    if (!/^(?:https?:|data:image\/)/i.test(favicon)) return;
    let icon = document.getElementById("nyxOuterTabIcon");
    if (!icon) {
      icon = document.createElementNS("http://www.w3.org/1999/xhtml", "link");
      icon.id = "nyxOuterTabIcon";
      icon.setAttribute("rel", "icon");
      document.documentElement.appendChild(icon);
    }
    icon.setAttribute("href", favicon.slice(0, 250000));
  };
  addEventListener("message", applyCloak);
})();
